@Controller
public class QuizController {
    private final QuizRepository quizzes; private final QuizJogadorRepository jogadores; private final QuizRespostaRepository respostas; private final QuizBancoPerguntaRepository banco;
    private final EventoRepository eventos; private final UsuarioRepository usuarios; private final InscricaoRepository inscricoes; private final ObjectMapper mapper; private final sistema.eventos.service.FileStorageService files;
    public QuizController(QuizRepository quizzes, QuizJogadorRepository jogadores, QuizRespostaRepository respostas, QuizBancoPerguntaRepository banco, EventoRepository eventos, UsuarioRepository usuarios, InscricaoRepository inscricoes, ObjectMapper mapper, sistema.eventos.service.FileStorageService files) {
        this.quizzes=quizzes; this.jogadores=jogadores; this.respostas=respostas; this.banco=banco; this.eventos=eventos; this.usuarios=usuarios; this.inscricoes=inscricoes; this.mapper=mapper; this.files=files;
    }

    @GetMapping("/organizador/quizzes") public String lista(Authentication auth, Model model) {
        Usuario u=usuario(auth); model.addAttribute("quizzes",quizzes.findByOrganizadorIdOrderByIdDesc(u.getId()));
        model.addAttribute("eventos",eventos.findByOrganizadorId(u.getId())); return "quiz-lista";
    }
    @GetMapping("/organizador/quizzes/novo") public String novo(@RequestParam Long eventoId, Authentication auth, Model model) {
        Evento e=eventos.findById(eventoId).orElseThrow(); if(!e.getOrganizador().getId().equals(usuario(auth).getId())) throw new RuntimeException("Evento não encontrado.");
        model.addAttribute("evento",e); return "quiz-editor";
    }
    @PostMapping("/organizador/quizzes/salvar") @Transactional public String salvar(@RequestParam Long eventoId, @RequestParam String dados, Authentication auth) throws IOException {
        Usuario u=usuario(auth); Evento e=eventos.findById(eventoId).orElseThrow(); if(!e.getOrganizador().getId().equals(u.getId())) throw new RuntimeException("Acesso negado.");
        QuizInput input=mapper.readValue(dados,QuizInput.class); if(input.titulo==null||input.titulo.isBlank()||input.perguntas==null||input.perguntas.isEmpty()) throw new IllegalArgumentException("Informe um título e ao menos uma pergunta.");
        Quiz q=new Quiz(); q.setEvento(e); q.setOrganizador(u); q.setTitulo(input.titulo.trim()); q.setDescricao(input.descricao); q.setCodigo(codigo());
        q.setPontosFacil(valor(input.pontosFacil,500)); q.setPontosMedio(valor(input.pontosMedio,1000)); q.setPontosDificil(valor(input.pontosDificil,1500));
        List<QuizBancoPergunta> pool=new ArrayList<>();
        for(QuestionInput qi:input.perguntas){
            QuizBancoPergunta origem;
            if(qi.bancoId!=null){if(pool.stream().anyMatch(x->x.getId().equals(qi.bancoId)))throw new IllegalArgumentException("A mesma pergunta do banco não pode ser adicionada duas vezes.");origem=banco.findWithOwnerById(qi.bancoId).orElseThrow(()->new IllegalArgumentException("Pergunta do banco não encontrada."));if(!origem.getOrganizador().getId().equals(u.getId()))throw new IllegalArgumentException("A pergunta não pertence ao seu banco.");}
            else {if(qi.enunciado==null||qi.enunciado.isBlank()||qi.alternativas==null||qi.alternativas.size()<2||qi.alternativas.stream().filter(a->a.correta).count()!=1)throw new IllegalArgumentException("Cada pergunta precisa de pelo menos duas alternativas e uma correta.");origem=new QuizBancoPergunta();origem.setOrganizador(u);origem.setEnunciado(qi.enunciado.trim());origem.setImagemUrl(blank(qi.imagemUrl));origem.setDificuldade(QuizDificuldade.valueOf(qi.dificuldade==null?"MEDIO":qi.dificuldade));origem.setSegundos(Math.max(5,Math.min(120,qi.segundos==null?20:qi.segundos)));origem.setBonus(Boolean.TRUE.equals(qi.bonus));int oi=0;for(OptionInput ai:qi.alternativas){if(ai.texto==null||ai.texto.isBlank())continue;QuizBancoAlternativa ba=new QuizBancoAlternativa();ba.setPergunta(origem);ba.setTexto(ai.texto.trim());ba.setImagemUrl(blank(ai.imagemUrl));ba.setCorreta(ai.correta);ba.setOrdem(oi++);origem.getAlternativas().add(ba);}if(origem.getAlternativas().size()<2)throw new IllegalArgumentException("Cada pergunta precisa de pelo menos duas alternativas.");banco.save(origem);}
            pool.add(origem);
        }
        int n=0; for(QuizBancoPergunta origem:pool){
            QuizPergunta p=new QuizPergunta(); p.setQuiz(q); p.setEnunciado(origem.getEnunciado()); p.setImagemUrl(origem.getImagemUrl()); p.setDificuldade(origem.getDificuldade()); p.setSegundos(origem.getSegundos()); p.setBonus(origem.getBonus()); p.setOrdem(n++);
            int j=0; for(QuizBancoAlternativa ba:origem.getAlternativas()){QuizAlternativa a=new QuizAlternativa();a.setPergunta(p);a.setTexto(ba.getTexto());a.setImagemUrl(ba.getImagemUrl());a.setCorreta(ba.isCorreta());a.setOrdem(j++);p.getAlternativas().add(a);}if(p.getAlternativas().size()>4)throw new IllegalArgumentException("Cada pergunta pode ter até quatro alternativas para exibição no telão.");q.getPerguntas().add(p);
        }
        quizzes.save(q); return "redirect:/organizador/quizzes/"+q.getId();
    }
    @GetMapping("/organizador/quizzes/{id}") @Transactional(readOnly=true) public String gerir(@PathVariable Long id,Authentication auth,Model model){Quiz q=owned(id,auth); model.addAttribute("quiz",q);model.addAttribute("rank",rank(q));model.addAttribute("qrData",qr(q.getCodigo()));model.addAttribute("roundStats",roundStats(q));return "quiz-anfitriao";}
    @PostMapping(value="/organizador/quizzes/imagem",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseBody public Map<String,String> imagem(@RequestPart("imagem") org.springframework.web.multipart.MultipartFile imagem){return Map.of("url",files.publicImageUrl(files.storeImage(imagem,"quiz")));}
    @GetMapping(value="/organizador/quizzes/banco",produces=MediaType.APPLICATION_JSON_VALUE) @ResponseBody public List<Map<String,Object>> perguntasBanco(Authentication auth){return banco.findByOrganizadorIdOrderByIdDesc(usuario(auth).getId()).stream().map(p->Map.of("id",p.getId(),"enunciado",p.getEnunciado(),"imagemUrl",p.getImagemUrl()==null?"":p.getImagemUrl(),"dificuldade",p.getDificuldade().name(),"segundos",p.getSegundos(),"bonus",p.getBonus(),"alternativas",p.getAlternativas().stream().map(a->Map.of("texto",a.getTexto(),"imagemUrl",a.getImagemUrl()==null?"":a.getImagemUrl(),"correta",a.isCorreta())).toList())).toList();}
    @PostMapping("/organizador/quizzes/{id}/iniciar") @Transactional public String iniciar(@PathVariable Long id,Authentication auth){Quiz q=owned(id,auth);if(q.getStatus()!=QuizStatus.RASCUNHO||q.getPerguntas().isEmpty())throw new IllegalArgumentException("Cadastre pelo menos uma pergunta antes de iniciar.");q.setStatus(QuizStatus.AGUARDANDO);q.setIniciadoEm(LocalDateTime.now());return "redirect:/organizador/quizzes/"+id;}
    @PostMapping("/organizador/quizzes/{id}/sortear/{dificuldade}") @Transactional public String sortear(@PathVariable Long id,@PathVariable QuizDificuldade dificuldade,Authentication auth){Quiz q=owned(id,auth);if(q.getStatus()!=QuizStatus.AGUARDANDO&&q.getStatus()!=QuizStatus.EM_ANDAMENTO)throw new IllegalArgumentException("Inicie a sala antes de sortear uma pergunta.");QuizPergunta anterior=currentQuestion(q);if(anterior!=null){for(QuizJogador jogador:q.getJogadores())if(!respostas.existsByJogadorIdAndPerguntaId(jogador.getId(),anterior.getId()))jogador.setSequencia(0);}List<QuizPergunta> candidates=q.getPerguntas().stream().filter(p->p.getDificuldade()==dificuldade&&!Boolean.TRUE.equals(p.getJaSorteada())).collect(Collectors.toCollection(ArrayList::new));if(candidates.isEmpty())throw new IllegalArgumentException("Não há mais perguntas "+label(dificuldade).toLowerCase()+" disponíveis nesta partida.");Collections.shuffle(candidates);QuizPergunta escolhida=candidates.get(0);escolhida.setJaSorteada(true);q.setPerguntaEmAndamentoId(escolhida.getId());q.setPerguntaAtual(q.getPerguntaAtual()+1);q.setPerguntaLiberadaEm(LocalDateTime.now());q.setStatus(QuizStatus.EM_ANDAMENTO);return "redirect:/organizador/quizzes/"+id;}
    @PostMapping("/organizador/quizzes/{id}/encerrar") @Transactional public String encerrar(@PathVariable Long id,Authentication auth){Quiz q=owned(id,auth);q.setStatus(QuizStatus.ENCERRADO);q.setEncerradoEm(LocalDateTime.now());return "redirect:/organizador/quizzes/"+id;}
    @GetMapping("/quiz/entrar/{codigo}") public String entrar(@PathVariable String codigo,Authentication auth,Model model){Quiz q=quizzes.findByCodigoIgnoreCase(codigo).orElseThrow();model.addAttribute("quiz",q);model.addAttribute("nomeSugerido",usuario(auth).getNome());return "quiz-entrar";}
    @GetMapping("/quiz/entrar") public String pin(){return "quiz-pin";}
    @PostMapping("/quiz/acessar") public String acessar(@RequestParam String codigo){Quiz q=quizzes.findByCodigoIgnoreCase(codigo.trim()).orElse(null);if(q==null)return "redirect:/quiz/entrar?invalido=true";return "redirect:/quiz/entrar/"+q.getCodigo();}
    @PostMapping("/quiz/entrar/{codigo}") @Transactional public String entrarPost(@PathVariable String codigo,@RequestParam(defaultValue="astronauta") String avatar,@RequestParam(required=false) String apelido,Authentication auth,RedirectAttributes flash){Quiz q=quizzes.findByCodigoIgnoreCase(codigo).orElseThrow();Usuario u=usuario(auth);
        if(u.getPerfil()!=Perfil.ROLE_PARTICIPANTE){flash.addFlashAttribute("erroEntrada","Esta sala é exclusiva para contas de participante.");return "redirect:/quiz/entrar/"+q.getCodigo();}
        Inscricao inscricao=inscricoes.findByParticipanteIdAndEventoIdComEvento(u.getId(),q.getEvento().getId()).orElse(null);
        if(inscricao==null||inscricao.getStatus()==StatusInscricao.CANCELADO){flash.addFlashAttribute("erroEntrada","Não encontramos uma inscrição ativa para este evento nesta conta. Confira se entrou com a mesma conta usada na inscrição.");return "redirect:/quiz/entrar/"+q.getCodigo();}
        if(q.getStatus()==QuizStatus.ENCERRADO){flash.addFlashAttribute("erroEntrada","Este quiz já foi encerrado.");return "redirect:/quiz/entrar/"+q.getCodigo();}
        QuizJogador jogador=jogadores.findByQuizIdAndUsuarioId(q.getId(),u.getId()).orElse(null);if(jogador==null){jogador=new QuizJogador();jogador.setQuiz(q);jogador.setUsuario(u);jogador.setApelido(normalizarApelido(apelido,u.getNome()));jogador.setAvatar(avatar(avatar));jogador.setEntrouEm(LocalDateTime.now());jogadores.save(jogador);}else if(jogador.getApelido()==null){jogador.setApelido(normalizarApelido(apelido,u.getNome()));}
        return "redirect:/quiz/jogar/"+q.getCodigo();
    }
    @GetMapping("/quiz/jogar/{codigo}") public String jogar(@PathVariable String codigo,Authentication auth,Model model){Quiz q=quizzes.findByCodigoIgnoreCase(codigo).orElseThrow();QuizJogador j=jogadores.findByQuizIdAndUsuarioId(q.getId(),usuario(auth).getId()).orElseThrow(()->new IllegalArgumentException("Entre no quiz antes de jogar."));model.addAttribute("quiz",q);model.addAttribute("jogador",j);return "quiz-jogar";}
    @GetMapping(value="/organizador/quizzes/{id}/anfitriao-estado",produces=MediaType.APPLICATION_JSON_VALUE) @ResponseBody @Transactional(readOnly=true) public Map<String,Object> estadoAnfitriao(@PathVariable Long id,Authentication auth){Quiz q=owned(id,auth);Map<String,Object> out=new LinkedHashMap<>();out.put("status",q.getStatus().name());out.put("codigo",q.getCodigo());out.put("totalJogadores",q.getJogadores().size());out.put("jogadores",q.getJogadores().stream().sorted(Comparator.comparing(QuizJogador::getEntrouEm)).map(j->Map.of("apelido",nomeJogador(j),"avatar",j.getAvatar(),"pontuacao",j.getPontuacao())).toList());out.put("disponiveis",Arrays.stream(QuizDificuldade.values()).collect(Collectors.toMap(Enum::name,d->(int)q.getPerguntas().stream().filter(p->p.getDificuldade()==d&&!Boolean.TRUE.equals(p.getJaSorteada())).count())));out.put("ranking",rank(q).stream().limit(5).map(j->Map.of("apelido",nomeJogador(j),"avatar",j.getAvatar(),"pontuacao",j.getPontuacao())).toList());QuizPergunta p=currentQuestion(q);if(p==null){out.put("fase","LOBBY");out.put("pergunta",null);out.put("respostas",0);return out;}long sinceRelease=Duration.between(q.getPerguntaLiberadaEm(),LocalDateTime.now()).toMillis();long remaining=Math.max(0,p.getSegundos()*1000L-Math.max(0,sinceRelease-5000));String phase=sinceRelease<5000?"LEITURA":remaining>0?"RESPONDENDO":"RESULTADO";List<QuizResposta> rs=respostas.findByPerguntaId(p.getId());boolean showResult=phase.equals("RESULTADO");Map<String,Object> question=new LinkedHashMap<>();question.put("id",p.getId());question.put("enunciado",p.getEnunciado());question.put("imagemUrl",files.publicImageUrl(p.getImagemUrl()));question.put("dificuldade",label(p.getDificuldade()));question.put("numero",q.getPerguntaAtual()+1);question.put("segundos",p.getSegundos());question.put("bonus",p.getBonus());question.put("tempoRestanteMs",sinceRelease<5000?5000-sinceRelease:remaining);question.put("alternativas",p.getAlternativas().stream().map(a->{Map<String,Object> option=new LinkedHashMap<>();option.put("id",a.getId());option.put("texto",a.getTexto());option.put("imagemUrl",files.publicImageUrl(a.getImagemUrl()));option.put("ordem",a.getOrdem());option.put("correta",showResult&&a.isCorreta());option.put("respostas",showResult?rs.stream().filter(r->r.getAlternativa()!=null&&r.getAlternativa().getId().equals(a.getId())).count():0);return option;}).toList());out.put("fase",phase);out.put("pergunta",question);out.put("respostas",rs.size());return out;}
    @GetMapping(value="/quiz/{codigo}/estado",produces=MediaType.APPLICATION_JSON_VALUE) @ResponseBody @Transactional(readOnly=true) public Map<String,Object> estado(@PathVariable String codigo,Authentication auth){Quiz q=quizzes.findByCodigoIgnoreCase(codigo).orElseThrow();QuizJogador me=jogadores.findByQuizIdAndUsuarioId(q.getId(),usuario(auth).getId()).orElseThrow();Map<String,Object> out=new LinkedHashMap<>();out.put("status",q.getStatus().name());out.put("titulo",q.getTitulo());out.put("pontuacao",me.getPontuacao());List<QuizJogador> ranking=rank(q);int posicao=posicao(ranking,me.getId());out.put("rank",ranking.stream().limit(5).map(x->Map.of("nome",nomeJogador(x),"avatar",x.getAvatar(),"pontuacao",x.getPontuacao())).toList());out.put("posicao",posicao);QuizPergunta p=currentQuestion(q);if(p==null){out.put("fase","LOBBY");out.put("pergunta",null);out.put("respondida",false);return out;}long sinceRelease=Duration.between(q.getPerguntaLiberadaEm(),LocalDateTime.now()).toMillis();long remaining=Math.max(0,p.getSegundos()*1000L-Math.max(0,sinceRelease-5000));String phase=sinceRelease<5000?"LEITURA":remaining>0?"RESPONDENDO":"RESULTADO";out.put("fase",phase);out.put("tempoRestanteMs",sinceRelease<5000?5000-sinceRelease:remaining);out.put("pergunta",Map.of("numero",q.getPerguntaAtual()+1,"segundos",p.getSegundos(),"alternativas",p.getAlternativas().stream().map(a->Map.of("id",a.getId(),"ordem",a.getOrdem(),"cor",List.of("red","blue","yellow","green").get(a.getOrdem()),"forma",List.of("▲","◆","●","■").get(a.getOrdem()))).toList()));QuizResposta resposta=respostas.findByJogadorIdAndPerguntaId(me.getId(),p.getId()).orElse(null);out.put("respondida",resposta!=null);if(phase.equals("RESULTADO"))out.put("resultado",Map.of("correta",resposta!=null&&resposta.isCorreta(),"pontos",resposta==null?0:resposta.getPontos(),"sequencia",me.getSequencia(),"posicao",posicao));return out;}
    @PostMapping(value="/quiz/{codigo}/responder",produces=MediaType.APPLICATION_JSON_VALUE) @ResponseBody @Transactional public Map<String,Object> responder(@PathVariable String codigo,@RequestParam Long alternativaId,Authentication auth){Quiz q=quizzes.findByCodigoIgnoreCase(codigo).orElseThrow();QuizJogador j=jogadores.findByQuizIdAndUsuarioId(q.getId(),usuario(auth).getId()).orElseThrow();QuizPergunta p=currentQuestion(q);if(q.getStatus()!=QuizStatus.EM_ANDAMENTO||p==null)throw new IllegalArgumentException("Ainda não há pergunta aberta.");if(respostas.existsByJogadorIdAndPerguntaId(j.getId(),p.getId()))throw new IllegalArgumentException("Resposta já enviada.");LocalDateTime inicioResposta=q.getPerguntaLiberadaEm().plusSeconds(5);if(LocalDateTime.now().isBefore(inicioResposta))throw new IllegalArgumentException("Aguarde a exibição das alternativas.");long elapsed=Duration.between(inicioResposta,LocalDateTime.now()).toMillis();if(elapsed>p.getSegundos()*1000L)throw new IllegalArgumentException("O tempo para responder terminou.");QuizAlternativa a=p.getAlternativas().stream().filter(x->x.getId().equals(alternativaId)).findFirst().orElseThrow();int points=0;if(a.isCorreta()){j.setSequencia(j.getSequencia()+1);int base=switch(p.getDificuldade()){case FACIL->q.getPontosFacil();case MEDIO->q.getPontosMedio();case DIFICIL->q.getPontosDificil();};double multiplier=j.getSequencia()>=4?2.0:j.getSequencia()==3?1.5:j.getSequencia()==2?1.2:1.0;points=(int)Math.round(base*Math.max(.2,1.0-(double)elapsed/(p.getSegundos()*1000L))*(Boolean.TRUE.equals(p.getBonus())?2:1)*multiplier);j.setPontuacao(j.getPontuacao()+points);}else j.setSequencia(0);QuizResposta r=new QuizResposta();r.setJogador(j);r.setPergunta(p);r.setAlternativa(a);r.setCorreta(a.isCorreta());r.setPontos(points);r.setTempoMs(elapsed);respostas.save(r);return Map.of("registrada",true);}
    @GetMapping("/organizador/quizzes/{id}/relatorio") @Transactional(readOnly=true) public String relatorio(@PathVariable Long id,Authentication auth,Model model){Quiz q=owned(id,auth);List<Map<String,Object>> questionStats=questionReports(q);model.addAttribute("quiz",q);model.addAttribute("rank",rank(q));model.addAttribute("stats",reportStats(q));model.addAttribute("questionReports",questionStats);model.addAttribute("hasCriticalQuestion",questionStats.stream().anyMatch(x->(Integer)x.get("percentual")<35));model.addAttribute("playerReports",playerReports(q));return "quiz-relatorio";}
    @GetMapping("/organizador/quizzes/{id}/relatorio.xlsx") @Transactional(readOnly=true) public void xlsx(@PathVariable Long id,Authentication auth,HttpServletResponse res)throws IOException {Quiz q=owned(id,auth);List<QuizJogador> ordem=rank(q);List<QuizPergunta> aplicadas=perguntasAplicadas(q);int quantidadeAplicada=aplicadas.size();List<QuizResposta> todas=respostas.findByJogadorQuizId(id);Map<String,QuizResposta> porPar=new HashMap<>();todas.forEach(r->porPar.put(r.getJogador().getId()+"-"+r.getPergunta().getId(),r));try(Workbook wb=new XSSFWorkbook()){CellStyle header=wb.createCellStyle();Font bold=wb.createFont();bold.setBold(true);header.setFont(bold);
        Sheet ps=wb.createSheet("Jogadores");Row h=ps.createRow(0);String[] ph={"Posição","Participante","Avatar","Pontuação","Acertos (%)","Sem resposta"};for(int c=0;c<ph.length;c++){h.createCell(c).setCellValue(ph[c]);h.getCell(c).setCellStyle(header);}for(int i=0;i<ordem.size();i++){QuizJogador j=ordem.get(i);List<QuizResposta> rs=todas.stream().filter(r->r.getJogador().getId().equals(j.getId())).toList();long ok=rs.stream().filter(QuizResposta::isCorreta).count();Row row=ps.createRow(i+1);row.createCell(0).setCellValue(i+1);row.createCell(1).setCellValue(j.getUsuario().getNome());row.createCell(2).setCellValue(j.getAvatar());row.createCell(3).setCellValue(j.getPontuacao());row.createCell(4).setCellValue(quantidadeAplicada==0?0:100.0*ok/quantidadeAplicada);row.createCell(5).setCellValue(Math.max(0,quantidadeAplicada-rs.size()));}
        Sheet qs=wb.createSheet("Perguntas");String[] qh={"Nº","Pergunta","Dificuldade","Corretas","Incorretas","Sem resposta","Acerto (%)","Tempo médio (ms)"};Row qrow=qs.createRow(0);for(int c=0;c<qh.length;c++){qrow.createCell(c).setCellValue(qh[c]);qrow.getCell(c).setCellStyle(header);}for(int i=0;i<aplicadas.size();i++){QuizPergunta p=aplicadas.get(i);List<QuizResposta> rs=todas.stream().filter(r->r.getPergunta().getId().equals(p.getId())).toList();long ok=rs.stream().filter(QuizResposta::isCorreta).count();Row row=qs.createRow(i+1);row.createCell(0).setCellValue(i+1);row.createCell(1).setCellValue(p.getEnunciado());row.createCell(2).setCellValue(p.getDificuldade().name());row.createCell(3).setCellValue(ok);row.createCell(4).setCellValue(rs.size()-ok);row.createCell(5).setCellValue(Math.max(0,ordem.size()-rs.size()));row.createCell(6).setCellValue(ordem.isEmpty()?0:100.0*ok/ordem.size());row.createCell(7).setCellValue(rs.stream().mapToLong(QuizResposta::getTempoMs).average().orElse(0));}
        Sheet as=wb.createSheet("Respostas");String[] ah={"Participante","Pergunta","Alternativa marcada","Correta","Pontos","Tempo (ms)"};Row arow=as.createRow(0);for(int c=0;c<ah.length;c++){arow.createCell(c).setCellValue(ah[c]);arow.getCell(c).setCellStyle(header);}int ri=1;for(QuizJogador j:ordem)for(QuizPergunta p:aplicadas){QuizResposta a=porPar.get(j.getId()+"-"+p.getId());Row row=as.createRow(ri++);row.createCell(0).setCellValue(j.getUsuario().getNome());row.createCell(1).setCellValue(p.getEnunciado());row.createCell(2).setCellValue(a==null?"Sem resposta":a.getAlternativa().getTexto());row.createCell(3).setCellValue(a!=null&&a.isCorreta()?"Sim":"Não");row.createCell(4).setCellValue(a==null?0:a.getPontos());row.createCell(5).setCellValue(a==null?0:a.getTempoMs());}
        for(Sheet s:List.of(ps,qs,as))for(int c=0;c<s.getRow(0).getLastCellNum();c++)s.autoSizeColumn(c);res.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");res.setHeader("Content-Disposition","attachment; filename=quiz-"+id+"-relatorio.xlsx");wb.write(res.getOutputStream());}}
    @GetMapping("/organizador/quizzes/{id}/relatorio.csv") public void csv(@PathVariable Long id,Authentication auth,HttpServletResponse res)throws IOException{Quiz q=owned(id,auth);res.setContentType("text/csv;charset=UTF-8");res.setHeader("Content-Disposition","attachment; filename=quiz-"+id+"-relatorio.csv");res.getWriter().write("\uFEFFJogador;Posição;Pontuação;Avatar\n");int i=0;for(QuizJogador j:rank(q))res.getWriter().write(csvEscape(j.getUsuario().getNome())+";"+(++i)+";"+j.getPontuacao()+";"+j.getAvatar()+"\n");res.getWriter().write("\nPergunta;Corretas;Incorretas;Sem resposta;Tempo médio (ms)\n");for(QuizPergunta p:perguntasAplicadas(q)){List<QuizResposta> rs=respostas.findByPerguntaId(p.getId());long ok=rs.stream().filter(QuizResposta::isCorreta).count();double avg=rs.stream().mapToLong(QuizResposta::getTempoMs).average().orElse(0);res.getWriter().write(csvEscape(p.getEnunciado())+";"+ok+";"+(rs.size()-ok)+";"+(q.getJogadores().size()-rs.size())+";"+Math.round(avg)+"\n");}}
    private Map<String,Object> reportStats(Quiz q){List<QuizResposta> all=respostas.findByJogadorQuizId(q.getId());int totalQuestoes=perguntasAplicadas(q).size();long correct=all.stream().filter(QuizResposta::isCorreta).count();long total=(long)q.getJogadores().size()*totalQuestoes;return Map.of("participantes",q.getJogadores().size(),"perguntas",totalQuestoes,"acerto",total==0?0:Math.round(100.0*correct/total),"semResposta",Math.max(0,total-all.size()),"duracao",q.getIniciadoEm()==null?0:Duration.between(q.getIniciadoEm(),q.getEncerradoEm()==null?LocalDateTime.now():q.getEncerradoEm()).toMinutes());}
    private List<Map<String,Object>> questionReports(Quiz q){List<Map<String,Object>> out=new ArrayList<>();for(QuizPergunta p:perguntasAplicadas(q)){List<QuizResposta> rs=respostas.findByPerguntaId(p.getId());long correct=rs.stream().filter(QuizResposta::isCorreta).count();out.add(Map.of("pergunta",p,"corretas",correct,"incorretas",rs.size()-correct,"semResposta",Math.max(0,q.getJogadores().size()-rs.size()),"percentual",q.getJogadores().isEmpty()?0:Math.round(100.0*correct/q.getJogadores().size()),"tempoMedio",Math.round(rs.stream().mapToLong(QuizResposta::getTempoMs).average().orElse(0))));}return out;}
    private Map<String,Object> roundStats(Quiz q){QuizPergunta p=currentQuestion(q);if(p==null)return Map.of("corretas",0,"incorretas",0,"semResposta",q.getJogadores().size());List<QuizResposta> rs=respostas.findByPerguntaId(p.getId());long correct=rs.stream().filter(QuizResposta::isCorreta).count();return Map.of("corretas",correct,"incorretas",rs.size()-correct,"semResposta",Math.max(0,q.getJogadores().size()-rs.size()));}
    private List<Map<String,Object>> playerReports(Quiz q){List<QuizResposta> all=respostas.findByJogadorQuizId(q.getId());int totalQuestoes=perguntasAplicadas(q).size();List<Map<String,Object>> out=new ArrayList<>();int pos=0;for(QuizJogador j:rank(q)){List<QuizResposta> rs=all.stream().filter(x->x.getJogador().getId().equals(j.getId())).toList();long correct=rs.stream().filter(QuizResposta::isCorreta).count();out.add(Map.of("jogador",j,"posicao",++pos,"corretas",correct,"percentual",totalQuestoes==0?0:Math.round(100.0*correct/totalQuestoes),"semResposta",Math.max(0,totalQuestoes-rs.size())));}double media=out.stream().mapToInt(x->(Integer)x.get("percentual")).average().orElse(0);for(Map<String,Object> row:out)row.put("abaixoMedia",(Integer)row.get("percentual")<media);return out;}
    private List<QuizPergunta> perguntasAplicadas(Quiz q){return q.getPerguntas().stream().filter(p->Boolean.TRUE.equals(p.getJaSorteada())).sorted(Comparator.comparing(QuizPergunta::getOrdem)).toList();}
    private List<QuizJogador> rank(Quiz q){return q.getJogadores().stream().sorted(Comparator.comparing(QuizJogador::getPontuacao).reversed().thenComparing(QuizJogador::getEntrouEm)).toList();}
    private QuizPergunta currentQuestion(Quiz q){Long id=q.getPerguntaEmAndamentoId();return id==null?null:q.getPerguntas().stream().filter(p->id.equals(p.getId())).findFirst().orElse(null);}
    private int posicao(List<QuizJogador> lista,Long id){for(int i=0;i<lista.size();i++)if(lista.get(i).getId().equals(id))return i+1;return lista.size()+1;}
    private String nomeJogador(QuizJogador jogador){return jogador.getApelido()==null||jogador.getApelido().isBlank()?jogador.getUsuario().getNome():jogador.getApelido();}
    private String normalizarApelido(String apelido,String nome){String value=apelido==null||apelido.isBlank()?nome:apelido.trim();value=value.replaceAll("[\\p{Cntrl}]"," ").replaceAll("\\s+"," ").trim();if(value.length()<2)value=nome.trim();return value.length()>24?value.substring(0,24):value;}
    private String label(QuizDificuldade d){return switch(d){case FACIL->"Fácil";case MEDIO->"Médio";case DIFICIL->"Difícil";};}
    private String qr(String codigo){try{String url=org.springframework.web.servlet.support.ServletUriComponentsBuilder.fromCurrentContextPath().path("/quiz/entrar/{codigo}").buildAndExpand(codigo).toUriString();ByteArrayOutputStream out=new ByteArrayOutputStream();MatrixToImageWriter.writeToStream(new QRCodeWriter().encode(url,BarcodeFormat.QR_CODE,280,280),"PNG",out);return "data:image/png;base64,"+Base64.getEncoder().encodeToString(out.toByteArray());}catch(Exception e){return "";}}
    private Quiz owned(Long id,Authentication a){Quiz q=quizzes.findFullById(id).orElseThrow();if(!q.getOrganizador().getId().equals(usuario(a).getId()))throw new RuntimeException("Acesso negado.");return q;}
    private Usuario usuario(Authentication a){return usuarios.findByEmailIgnoreCase(a.getName()).orElseThrow();}
    private String codigo(){java.security.SecureRandom random=new java.security.SecureRandom();String x;do{x=random.ints(6,0,10).mapToObj(String::valueOf).collect(Collectors.joining());}while(quizzes.existsByCodigoIgnoreCase(x));return x;}
    private int valor(Integer x,int d){return x==null?d:Math.max(1,Math.min(10000,x));} private String blank(String x){return x==null||x.isBlank()?null:x.trim();} private String avatar(String x){return List.of("astronauta","raposa","gato","robo","coruja","capivara").contains(x)?x:"astronauta";}
    private String csvEscape(String s){return "\""+s.replace("\"","\"\"")+"\"";}
    public static class QuizInput {public String titulo,descricao; public Integer pontosFacil,pontosMedio,pontosDificil,quantidadeFacil,quantidadeMedio,quantidadeDificil; public List<QuestionInput> perguntas;}
    public static class QuestionInput {public Long bancoId;public String enunciado,imagemUrl,dificuldade;public Integer segundos;public Boolean bonus;public List<OptionInput> alternativas;}
    public static class OptionInput {public String texto,imagemUrl;public boolean correta;}
}
